#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    long long budget;
    scanf("%d %lld", &n, &budget);
    vector<long long> base(n), cost(n);
    for (auto &x : base) scanf("%lld", &x);
    for (auto &x : cost) scanf("%lld", &x);
    long long lo = LLONG_MAX, hi = LLONG_MAX;
    for (int i = 0; i < n; i++) {
        lo = min(lo, base[i]);
        hi = min(hi, base[i] * (1 + budget / cost[i]));
    }
    // Binary search the largest throughput whose minimum total upgrade cost fits the budget.
    // Since target <= hi, every term (target-1)/base[i]*cost[i] stays <= budget.
    while (lo < hi) {
        long long target = lo + (hi - lo + 1) / 2, spent = 0;
        for (int i = 0; i < n && spent <= budget; i++) spent += (target - 1) / base[i] * cost[i];
        if (spent <= budget) lo = target;
        else hi = target - 1;
    }
    printf("%lld\n", lo);
}

import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return null;
        ByteArrayOutputStream sb = new ByteArrayOutputStream();
        while (c != -1 && c > ' ') { sb.write(c); c = read(); }
        return sb.toString(java.nio.charset.StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long budget = nextLong();
        long[] base = new long[n], cost = new long[n];
        for (int i = 0; i < n; i++) base[i] = nextLong();
        for (int i = 0; i < n; i++) cost[i] = nextLong();
        long lo = Long.MAX_VALUE, hi = Long.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            lo = Math.min(lo, base[i]);
            hi = Math.min(hi, base[i] * (1 + budget / cost[i]));
        }
        // Binary search the largest throughput whose minimum total upgrade cost fits the budget.
        // Since target <= hi, every term (target-1)/base[i]*cost[i] stays <= budget.
        while (lo < hi) {
            long target = lo + (hi - lo + 1) / 2, spent = 0;
            for (int i = 0; i < n && spent <= budget; i++) spent += (target - 1) / base[i] * cost[i];
            if (spent <= budget) lo = target;
            else hi = target - 1;
        }
        System.out.println(lo);
    }
}

